spiner() {
  local PID=$1
  local DELAY=0.1
  local SPIN='|/-\'
  while [ "$(ps a | awk '{print $1}' | grep $PID)" ]; do
    local temp=${SPIN#?}
    printf " [%c]  " "$SPIN"
    local SPIN=$temp${SPIN%"$temp"}
    sleep $delay
    printf "\b\b\b\b\b\b"
    printf "    \b\b\b\b"
  done
}

